{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 실행 계획을 해석해 병목을 특정할 수 있는지 검증한다. 개선 방법이나 성과 자체보다 실행 계획의 관찰 내용을 병목 판단으로 연결한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "운영 화면의 신고 목록 조회 쿼리가 3.2초 걸렸던 상황이다.",
          "task": "실행 계획을 통해 조회 지연을 일으키는 병목을 좁혀야 했다.",
          "action": "실행 계획에서 확인한 접근 방식이나 처리량 등의 단서를 실제 조회 조건 및 조인 구조와 연결해 병목을 판단한 내용을 설명한다.",
          "result": "실행 계획의 어떤 관찰이 특정 병목을 가리켰는지 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "실행 계획을 근거로 조회 쿼리의 병목을 좁힌 판단",
          "판단의 근거가 된 실행 계획의 구체적인 관찰 내용",
          "관찰 내용이 해당 쿼리의 조회 조건이나 조인 구조에서 지연을 유발한다고 본 연결 설명"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 쿼리를 3.2초에서 0.4초로 줄이셨던데요, 실행 계획에서 무엇을 보고 병목을 좁히셨어요?",
      "answerTip": "당시 경험을 떠올리며 차근차근 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획의 구체적인 관찰 내용을 제시하고 이를 근거로 병목을 명확히 특정한다.",
            "관찰 내용이 조회 조건이나 조인 구조와 맞물려 지연을 일으키는 이유를 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "실행 계획에서 확인한 단서와 병목 판단을 제시하지만 관찰 내용의 구체성이 부족하다.",
            "해당 단서와 쿼리 지연의 연결은 설명하나 조회 조건이나 조인 구조에 대한 설명이 부분적이다."
          ]
        },
        "poor": {
          "criteria": [
            "실행 계획에서 무엇을 확인했는지 밝히지 못하거나 병목 판단의 근거가 불분명하다.",
            "개선 방법이나 속도 변화만 설명하고 실행 계획의 관찰 내용과 병목 사이의 연결을 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 발생한 오류를 로그로 추적해 원인을 좁힐 수 있는지 검증한다. 알림 중복 발송의 원인을 판단하는 데 결정적이었던 로그 흔적과 그 해석에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 후 같은 알림이 두 번 발송되는 오류가 발생했다.",
          "task": "로그를 근거로 알림 중복 발송의 원인을 좁혀야 했다.",
          "action": "원인 판단에 결정적이었던 로그 흔적을 짚고, 그 흔적이 어떤 실행 상황을 보여 주었는지 설명한다.",
          "result": "로그 흔적에서 오류 원인으로 이어지는 판단 근거가 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "오류 원인을 좁히는 데 결정적이었던 로그 흔적",
          "해당 흔적에서 확인한 실행 시점이나 실행 주체 등 구체적인 관찰 내용",
          "관찰 내용이 알림 중복 발송의 원인을 가리킨다고 판단한 이유"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 추적하셨던데요, 로그의 어떤 흔적이 원인을 좁히는 결정적인 근거였어요?",
      "answerTip": "기억에 남는 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "원인 추적에 결정적이었던 로그 흔적과 그 안에서 확인한 실행 정보를 구체적으로 제시한다.",
            "로그의 관찰 내용이 알림 중복 발송의 원인을 가리키는 이유를 논리적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "원인 판단에 사용한 로그 흔적을 제시하지만 실행 시점이나 실행 주체 등에 대한 설명이 구체적이지 않다.",
            "로그 흔적과 오류 원인의 연결은 제시하나 판단 이유에 대한 설명이 부분적이다."
          ]
        },
        "poor": {
          "criteria": [
            "로그를 확인했다고만 답하고 원인 판단에 사용한 구체적인 흔적을 제시하지 못한다.",
            "원인이나 수정 내용만 설명하고 로그의 관찰 내용이 그 원인을 뒷받침하는 이유를 설명하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "현업 요청의 목적을 해석해 요구사항 범위를 구체화하는 판단을 검증한다. 세탁소 인터뷰 내용을 근거로 당시 구현 범위를 정한 판단에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 인터뷰에서 예약 서비스에 대한 요청을 수집한 상황이 제시된다.",
          "task": "수집한 요청을 요구사항 정의서의 구현 범위로 구체화해야 했던 과제가 드러난다.",
          "action": "인터뷰에서 확인한 요청의 목적과 필요성을 근거로 포함하거나 제외할 범위를 판단한 행동이 설명된다.",
          "result": "당시 정한 구현 범위와 인터뷰 근거 사이의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "당시 구현 범위를 정한 판단 기준",
          "판단의 근거가 된 세탁소 인터뷰의 구체적인 요청과 목적",
          "해당 근거가 요구사항의 포함 또는 제외 결정으로 이어진 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 요구사항 정의서를 작성하셨던데요, 당시 구현 범위는 세탁소 인터뷰에서 무엇을 보고 정하셨어요?",
      "answerTip": "당시 경험을 차근차근 떠올려 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구현 범위의 판단 기준을 구체적으로 설명한다.",
            "인터뷰에서 확인한 요청과 그 목적을 실제 내용으로 제시한다.",
            "요청의 목적이 요구사항의 포함 또는 제외 결정으로 이어진 이유를 일관되게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "구현 범위의 판단 기준은 제시하지만 구체성이 부족하다.",
            "인터뷰 요청은 언급하지만 목적이나 범위 결정과의 연결이 부분적으로만 드러난다."
          ]
        },
        "poor": {
          "criteria": [
            "구현 범위를 정한 판단 기준이 드러나지 않는다.",
            "인터뷰를 진행했다는 사실만 설명하거나 요청 내용과 범위 결정의 연결을 제시하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황을 화면 단위의 기능 흐름으로 구체화하는 설계 판단을 검증한다. 화면설계서에서 예외 상황의 화면 전환을 결정한 지점 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "예약 서비스 화면설계서에 반영한 예외 상황 하나가 제시된다.",
          "task": "해당 상황에서 사용자가 보게 될 화면 흐름을 정해야 했던 과제가 드러난다.",
          "action": "예외 발생 조건과 화면 상태를 바탕으로 화면 전환을 결정한 판단이 설명된다.",
          "result": "예외 상황에서 어떤 화면 상태로 이어지도록 설계했는지 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "예외 상황의 화면 전환에서 고민한 구체적인 설계 결정",
          "그 결정을 필요하게 만든 예외 발생 조건과 화면 상태",
          "설계한 화면 전환과 해당 조건 사이의 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨던데요, 예외 상황의 화면 전환에서 가장 고민하신 결정은 뭐였어요?",
      "answerTip": "기억에 남는 한 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 상황의 화면 전환에 관한 설계 결정을 구체적으로 설명한다.",
            "예외가 발생하는 조건과 당시 화면 상태를 명확히 제시한다.",
            "해당 조건에서 설계한 화면 상태로 이어져야 하는 이유를 일관되게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황의 화면 전환 결정은 제시하지만 화면 상태나 발생 조건의 설명이 부족하다.",
            "설계한 화면 흐름은 드러나지만 예외 조건과의 연결이 부분적으로만 설명된다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황의 화면 전환에 관한 구체적인 설계 결정이 드러나지 않는다.",
            "화면설계서의 분량이나 도구 사용만 설명하고 예외 조건과 화면 흐름의 연결을 제시하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "투약 전 처방 내용을 확인한 결과를 근거로, 의심스러운 처방의 수행을 보류한 판단이 타당했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량에 이상이 있었던 상황이 제시된다.",
          "task": "해당 처방을 그대로 수행해도 되는지 투약 전에 판단해야 했음이 드러난다.",
          "action": "처방 용량을 무엇과 대조했고, 확인된 차이를 왜 투약 보류의 근거로 삼았는지 설명한다.",
          "result": "확인된 사실과 투약 보류 결정 사이의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "투약 보류를 결정한 구체적인 확인 결과",
          "처방 용량의 이상 여부를 판단하기 위해 대조한 정보",
          "확인된 차이가 처방을 그대로 수행하기 어렵다는 판단으로 이어진 이유"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 진통제 처방 오류를 발견하셨던데요, 투약 보류는 어떤 확인 결과를 근거로 결정하셨어요?",
      "answerTip": "당시 상황을 떠올려 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "투약 보류의 근거가 된 확인 결과와 대조한 정보를 구체적으로 설명한다.",
            "확인된 차이 때문에 처방을 그대로 수행하기 어렵다고 판단한 이유가 명확하고 타당하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "처방 용량의 차이와 투약 보류의 관련성은 설명하지만, 대조한 정보나 확인 결과가 구체적이지 않다.",
            "투약을 보류한 이유는 드러나지만 확인 사실과 결정 사이의 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "이상하게 느꼈다는 설명에 그치며 대조한 정보와 확인 결과를 제시하지 못한다.",
            "투약 보류 결정의 근거를 설명하지 못하거나 확인된 차이와 무관한 이유를 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태 관찰 기록 업무에서 실제 변화를 정확하게 남기기 위해 중점을 둔 기록 행동을 확인한다. 질문의 초점은 상태 변화 기록이며 보고나 인수인계 수행 여부는 별도로 요구하지 않는다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 전후 환자의 활력징후와 통증을 관찰하고 기록한 업무 맥락이 제시된다.",
          "task": "관찰한 환자 상태의 변화를 간호 기록에 정확히 남겨야 했음이 드러난다.",
          "action": "상태 변화 기록에서 중점을 둔 부분을 실제 관찰 내용과 기록 행동으로 설명한다.",
          "result": "기록에서 환자의 상태 변화가 구체적으로 드러나도록 한 방식이 확인된다."
        },
        "expectedEvidence": [
          "상태 변화 기록에서 가장 신경 쓴 부분",
          "그 부분에 주의를 기울인 이유가 된 실제 관찰 내용",
          "관찰한 변화를 정확히 드러내기 위해 실제로 기록한 방식"
        ]
      },
      "question": "푸른결종합병원에서 수술 전후 환자의 활력징후와 통증 관찰 기록을 맡으셨던데요, 상태 변화 기록에서 가장 신경 쓰신 부분은 무엇이었어요?",
      "answerTip": "직접 하신 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
